      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "FAD is synthesized from riboflavin (vitamin B₂).",
      "evidence": "Nutritional biochemistry: riboflavin is the precursor for the flavin coenzymes FMN and FAD.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 4,
      "claim": "Therefore riboflavin is required for the obligatory first step of fatty‑acid β‑oxidation.",
      "evidence": "Logical deduction: the first step needs FAD, and FAD is derived from riboflavin.",
      "weight": 0.15,
      "depends_on": [2, 3]
    },
